import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const h=JSON.parse('{"title":"Source audit and reuse decisions","description":"","frontmatter":{},"headers":[],"relativePath":"reuse/source-audit.md","filePath":"reuse/source-audit.md","lastUpdated":1794374806000}'),n={name:"reuse/source-audit.md"};function i(s,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="source-audit-and-reuse-decisions" tabindex="-1">Source audit and reuse decisions <a class="header-anchor" href="#source-audit-and-reuse-decisions" aria-label="Permalink to &quot;Source audit and reuse decisions&quot;">​</a></h1><p><strong>Snapshot: November 10, 2026.</strong> This is a targeted inspection of the paths and ranges below. It does not certify either Ordo generation as production-ready. Donor tests were not executed in this review. All links identify immutable commits rather than moving default branches.</p><h2 id="source-register" tabindex="-1">Source register <a class="header-anchor" href="#source-register" aria-label="Permalink to &quot;Source register&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Repository and pinned commit</th><th>Inspection</th></tr></thead><tbody><tr><td>H</td><td><code>StudioOrdo/ordo</code> · <code>39138562f112bed79babf5824d887dfef1b8ace6</code></td><td>Historical Rust daemon; job, event and graph paths below</td></tr><tr><td>C</td><td><code>StudioOrdo/ordo</code> · <code>cea316ac18bdac70e83a6b63bb60ff5459f8f4be</code></td><td>Current rebuild; gateway and TypeScript contracts below</td></tr><tr><td>E</td><td><code>kaw393939/ordo_executor</code> · <code>c417ab21e390796e1e57b534488deca13d866b10</code></td><td>Owner-only executor review; no source copied into this repository</td></tr><tr><td>W</td><td><code>kaw393939/is373-ai-chat</code> · <code>aea8dc003975d11dfb978f637887400ff646b55d</code></td><td>Browser stream decoding and session ownership</td></tr></tbody></table><p>The <a href="/knowledge-lab/source-ledger.json">machine-readable ledger</a> records blob identities and inspection scope. Commit pins establish which source was reviewed; they do not establish correctness, execution results or permission to relicense it.</p><h2 id="h-01-·-durable-task-kernel-—-adapt-first" tabindex="-1">H-01 · Durable task kernel — adapt first <a class="header-anchor" href="#h-01-·-durable-task-kernel-—-adapt-first" aria-label="Permalink to &quot;H-01 · Durable task kernel — adapt first&quot;">​</a></h2><p>Source: <a href="https://github.com/StudioOrdo/ordo/blob/39138562f112bed79babf5824d887dfef1b8ace6/crates/ordo-daemon/src/kernel.rs" target="_blank" rel="noreferrer"><code>crates/ordo-daemon/src/kernel.rs</code></a>, inspected lines 1–620 and 1120–1340.</p><p><code>validate_task_dag</code> checks duplicate keys, missing dependencies and cycles. <code>create_job_from_template_with_idempotency</code> fingerprints the request and compiled plan, returns the existing job for an equivalent request, rejects a conflicting request key, and inserts jobs, tasks, dependencies and events within one transaction. This is substantially closer to the desired engine than a new in-memory scheduler.</p><p><code>claim_ready_task</code> uses a guarded update, increments <code>attempt_count</code>, records a lease and appends an event. Keep those behaviors. The completion path calls <code>ensure_task_lease_owner</code>, whose inspected query checks a running task and matching worker ID, but not the lease deadline or a specific attempt/epoch. A late result from an earlier attempt could match a reused worker identity. <strong>Require job, task, worker, attempt/epoch, unexpired lease and expected status in the result-acceptance transaction.</strong></p><p>Also review the meaning of <code>skipped</code>: <code>ready_task_keys</code> and progress calculation treat it as satisfied. A skipped required evidence-validation stage must not accidentally authorize publication.</p><p><strong>Transfer tests:</strong> duplicate DAG key; cycle; missing dependency; same request/key replay; same key with changed request; two competing claims; expired result before reclamation; stale result after the same worker name receives a new lease; required-stage skip. See the <a href="./../engineering/examples#lease-ownership">lease lab</a>.</p><h2 id="h-02-·-durable-event-log-—-adapt-do-not-expose-raw-replay" tabindex="-1">H-02 · Durable event log — adapt, do not expose raw replay <a class="header-anchor" href="#h-02-·-durable-event-log-—-adapt-do-not-expose-raw-replay" aria-label="Permalink to &quot;H-02 · Durable event log — adapt, do not expose raw replay&quot;">​</a></h2><p>Source: <a href="https://github.com/StudioOrdo/ordo/blob/39138562f112bed79babf5824d887dfef1b8ace6/crates/ordo-daemon/src/events.rs" target="_blank" rel="noreferrer"><code>crates/ordo-daemon/src/events.rs</code></a>, entire file inspected.</p><p><code>append_realtime_event_tx</code> shares the caller&#39;s SQLite transaction and assigns a database cursor. <code>replay_events</code> orders after a cursor and caps page size. Existing tests include <code>serializes_job_event_shape</code> and <code>replay_after_cursor_returns_reconnect_gap</code>.</p><p>The replay helper has no viewer or library argument. Its use behind a public endpoint therefore requires a new access-scoped query boundary; upstream authorization is not established by this file. <code>event_from_row</code> replaces malformed payload JSON with <code>{}</code>. In a durable evidence system, corruption must produce a diagnostic or an explicit quarantined record, not silently normal-looking data.</p><p><strong>Transfer tests:</strong> rollback leaves neither state nor event; unauthorized run/library cursors reveal no payload; reconnect fetches each committed event once at the consumer; retention gap requests a fresh authorized snapshot; corrupt stored payload is reported. Cursor monotonicity does not imply a gap-free global sequence, nor does a cursor confer permission.</p><h2 id="h-03-·-candidate-graph-—-preserve-review-redesign-canonical-identity" tabindex="-1">H-03 · Candidate graph — preserve review, redesign canonical identity <a class="header-anchor" href="#h-03-·-candidate-graph-—-preserve-review-redesign-canonical-identity" aria-label="Permalink to &quot;H-03 · Candidate graph — preserve review, redesign canonical identity&quot;">​</a></h2><p>Source: <a href="https://github.com/StudioOrdo/ordo/blob/39138562f112bed79babf5824d887dfef1b8ace6/crates/ordo-daemon/src/knowledge_graph.rs" target="_blank" rel="noreferrer"><code>crates/ordo-daemon/src/knowledge_graph.rs</code></a>, inspected lines 1–290 and 510–790.</p><p>Useful structures include node/edge candidates, evidence references, provenance, visibility ceilings, promotion outcomes and one-hop traversal. The file uses SHA-256. Its deterministic extraction assigns illustrative confidence values and derives an edge from selected extracted labels; this is not a calibrated entity-resolution model.</p><p>Candidate hashes incorporate labels, evidence and provenance. That can identify an extraction proposal, but must not define a canonical person&#39;s or event&#39;s identity. The same entity in a new source should not acquire a new canonical ID merely because its evidence changed.</p><p><code>promote_edge_candidate</code> calls endpoint promotions and then writes edges, evidence, candidate state, promotion history and events. It accepts <code>&amp;Connection</code> and does not itself establish the enclosing transaction. A caller could pass a transaction; <strong>atomicity must be made explicit and tested at the command boundary</strong>, not inferred from the function name. Require an authenticated reviewer, approved proposal digest and expected graph revision before any canonical write.</p><p><code>graph_one_hop_neighborhood</code> filters edges and nodes separately. The new projection must suppress an edge unless both endpoints and its evidence are visible. Do not leak concealed endpoint identifiers through an otherwise visible edge.</p><p><strong>Transfer tests:</strong> partial promotion fault rolls back every write; endpoint rejection blocks the edge; new source does not duplicate canonical identity; qualifiers distinguish claims; public traversal reveals no hidden endpoints. See the <a href="./../engineering/examples#atomic-publication">publication lab</a>.</p><h2 id="c-01-·-rust-realtime-gateway-—-reuse-the-boundary-repair-the-transport" tabindex="-1">C-01 · Rust realtime gateway — reuse the boundary, repair the transport <a class="header-anchor" href="#c-01-·-rust-realtime-gateway-—-reuse-the-boundary-repair-the-transport" aria-label="Permalink to &quot;C-01 · Rust realtime gateway — reuse the boundary, repair the transport&quot;">​</a></h2><p>Sources: <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/crates/ordo-realtime-gateway/src/app.rs" target="_blank" rel="noreferrer"><code>app.rs</code></a>, <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/crates/ordo-realtime-gateway/src/session.rs" target="_blank" rel="noreferrer"><code>session.rs</code></a>, <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/crates/ordo-realtime-gateway/src/provider.rs" target="_blank" rel="noreferrer"><code>provider.rs</code></a>, and <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/crates/ordo-realtime-gateway/src/sse.rs" target="_blank" rel="noreferrer"><code>sse.rs</code></a>, entire files inspected.</p><p>Keep typed command/event boundaries, the separate provider adapter and bounded-time delta batching. Existing SSE tests cover LF/CRLF framing and multiline data. They do not prove correctness when network chunks split a UTF-8 character.</p><table tabindex="0"><thead><tr><th>Observation in inspected source</th><th>Required change</th></tr></thead><tbody><tr><td><code>String::from_utf8_lossy</code> is applied independently to byte chunks</td><td>Incremental UTF-8 decoding or complete-byte-frame assembly; test every split point</td></tr><tr><td><code>[DONE]</code> produces completed output while finish reasons are not normalized</td><td>Map provider outcomes to complete/incomplete/refused/failed; transport termination alone is not success</td></tr><tr><td>EOF before the marker already raises an error</td><td>Preserve this protection; do not regress it</td></tr><tr><td>Receive loop awaits generation serially</td><td>Cancellation must remain responsive while generation is active</td></tr><tr><td>Provider absent means canned local fallback</td><td>Explicit <code>mock</code> mode and visible limitations; never silently label canned output as model inference</td></tr><tr><td>Gateway routes show permissive CORS and no local authentication guard</td><td>Establish authenticated run ownership and origin policy for hosted use; upstream defenses were not inspected</td></tr><tr><td>Bind address is loopback and invalid port falls back silently</td><td>Typed deployment configuration; invalid supplied values fail startup</td></tr></tbody></table><p>The business-specific system prompt and client-supplied UI capability descriptions must not become the research service&#39;s authorization system. Preserve the idea of context, but derive permission-bearing context on the server.</p><h2 id="c-02-·-prototype-event-storage-—-replace-the-adapter" tabindex="-1">C-02 · Prototype event storage — replace the adapter <a class="header-anchor" href="#c-02-·-prototype-event-storage-—-replace-the-adapter" aria-label="Permalink to &quot;C-02 · Prototype event storage — replace the adapter&quot;">​</a></h2><p>Source: <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/lib/workflow/event-store.ts" target="_blank" rel="noreferrer"><code>lib/workflow/event-store.ts</code></a>, entire file inspected.</p><p>It serializes writes through a process-local Promise queue, rewrites <code>.data/workflow-events.json</code>, and renames a temporary file. This is not cross-process coordination or a transaction across application records. Its reader catches all errors and starts empty, conflating a missing development file with malformed data or denied access.</p><p>Retain event vocabulary if useful. Replace persistence with the transaction-owned store. A corrupt library should fail visibly; startup must not erase history by treating corruption as a fresh installation.</p><h2 id="c-03-·-result-envelopes-and-projections-—-retain-explicit-limitations" tabindex="-1">C-03 · Result envelopes and projections — retain explicit limitations <a class="header-anchor" href="#c-03-·-result-envelopes-and-projections-—-retain-explicit-limitations" aria-label="Permalink to &quot;C-03 · Result envelopes and projections — retain explicit limitations&quot;">​</a></h2><p>Sources: <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/lib/ordo/executor.ts" target="_blank" rel="noreferrer"><code>lib/ordo/executor.ts</code></a> and <a href="https://github.com/StudioOrdo/ordo/blob/cea316ac18bdac70e83a6b63bb60ff5459f8f4be/lib/ordo/projection.ts" target="_blank" rel="noreferrer"><code>lib/ordo/projection.ts</code></a>, entire files inspected.</p><p>The invocation, provider mode, artifacts, evidence and limitations fields are good contract material. But <code>createTaskResultEnvelope</code> fills a missing <code>contentHash</code> with an FNV-1a digest of labels and references, not artifact bytes. <strong>Separate metadata fingerprints from cryptographic artifact digests; never manufacture byte-integrity evidence.</strong></p><p>Projection schema versions and explicit visibility/capability fields are useful. Timestamp plus event-count comparisons are not a replacement for a durable authorized cursor. Regex text filters are defense-in-depth only, not complete secret removal or access control.</p><h2 id="e-01-·-owner-only-executor-lab-—-review-not-automatic-publication" tabindex="-1">E-01 · Owner-only executor lab — review, not automatic publication <a class="header-anchor" href="#e-01-·-owner-only-executor-lab-—-review-not-automatic-publication" aria-label="Permalink to &quot;E-01 · Owner-only executor lab — review, not automatic publication&quot;">​</a></h2><p>Owner-only source: <code>kaw393939/ordo_executor</code> at the pinned E commit. Relevant paths are <code>src/executor.rs</code>, <code>src/entity_disambiguate.rs</code>, <code>src/graph_promote.rs</code> and <code>src/vector_index.rs</code>.</p><p>The result-envelope validator checks outcome shape, evidence presence, lengths and forbidden output keys. It is not a complete secret-value classifier. The entity-hint reader keys a single hint by normalized name, and later inserts can replace an earlier same-name hint. The classifier&#39;s fixed confidence floors are heuristics, not calibrated identity probabilities. Use name-to-many candidate generation with type, time, geography and authority scope instead.</p><p>Graph promotion writes reviewed local artifacts after an explicit approval flag. That is useful staging behavior, not transactional publication into the new canonical graph. Bind approval to exact proposal content and a base revision. The vector index is explicitly a hashed lexical baseline, not semantic embeddings or ANN search.</p><p>Private code stays private unless a later, explicitly scoped extraction authorizes publication and completes the reuse review. The public documentation examples are newly written synthetic fixtures, not copies from that lab.</p><h2 id="w-01-·-streaming-workshop-—-transfer-behavior-and-tests" tabindex="-1">W-01 · Streaming workshop — transfer behavior and tests <a class="header-anchor" href="#w-01-·-streaming-workshop-—-transfer-behavior-and-tests" aria-label="Permalink to &quot;W-01 · Streaming workshop — transfer behavior and tests&quot;">​</a></h2><p>Source: <a href="https://github.com/kaw393939/is373-ai-chat/blob/aea8dc003975d11dfb978f637887400ff646b55d/frontend/src/api.ts" target="_blank" rel="noreferrer"><code>frontend/src/api.ts</code></a>, entire file inspected.</p><p><code>consume</code> incrementally decodes bytes, validates frame order and rejects missing terminal completion. <code>parseEvent</code> distinguishes complete, failed, cancelled, interrupted, incomplete and refused outcomes. <code>sessionStamp</code>/<code>ownsSession</code> prevent obsolete account work from being accepted by the current view.</p><p>Transfer those requirements to the Svelte client. Add bounded buffers, run/library-scoped replay and revision-pinned evidence. Do not copy the React/Python stack merely to reuse a protocol. Referenced donor test suites require their own execution evidence before claiming reuse validation.</p><h2 id="reuse-rights-and-limits" tabindex="-1">Reuse rights and limits <a class="header-anchor" href="#reuse-rights-and-limits" aria-label="Permalink to &quot;Reuse rights and limits&quot;">​</a></h2><p>The historical Ordo snapshot includes an <a href="https://github.com/StudioOrdo/ordo/blob/39138562f112bed79babf5824d887dfef1b8ace6/LICENSE" target="_blank" rel="noreferrer">AGPL license file</a>. Before importing source, record the exact applicable license, notices, ownership and dependency obligations. Do not assume current and historical trees have identical licensing or that code can be relicensed because repositories share an owner. The initial documentation change imports no donor implementation.</p>',47)])])}const b=t(n,[["render",i]]);export{h as __pageData,b as default};
